-- Layercake.usp_load_brnz_concession (src/sql/Layercake/Procedures/Layercake.usp_load_brnz_concession.sql)
/*====================================================================
    Layercake.usp_load_brnz_concession
    Bronze layer - CE.vwConcessionType -> Layercake.brnz_concession
    1:1 landing keyed on apuk_concessiontypeid (Q-008): insert new, update
    changed (and restore reappearing), soft-delete gone; row-count check
    (RULE-005); logged. apuk_dualmembership is not landed (Q-025).
====================================================================*/
CREATE OR ALTER PROCEDURE Layercake.usp_load_brnz_concession
    @run_id uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @run_id IS NULL SET @run_id = NEWID();

    DECLARE @log_id    bigint,
            @ins       int,
            @upd       int,
            @del       int,
            @src_count bigint,
            @tgt_count bigint,
            @err       nvarchar(4000);

    BEGIN TRY
        EXEC Layercake.usp_etl_log_start @run_id, 'bronze', 'brnz_concession', @log_id OUTPUT;

        -- Staged in the target's types with the key NOT NULL and unique: a NULL
        -- key fails the load with 515 and a duplicate key with 2627, before
        -- bronze is touched; no row is skipped (answers 2026-10-27).
        CREATE TABLE #src_concession
        (
            apuk_concessiontypeid      uniqueidentifier NOT NULL PRIMARY KEY CLUSTERED,
            apuk_name                  nvarchar(100)  COLLATE DATABASE_DEFAULT NULL,
            apuk_discount              decimal(38, 2) NULL,
            product_number             nvarchar(4000) COLLATE DATABASE_DEFAULT NULL,
            statecode                  int            NULL,
            apuk_perpetualnonperpetual int            NULL
        );

        INSERT INTO #src_concession
            (apuk_concessiontypeid, apuk_name, apuk_discount, product_number, statecode, apuk_perpetualnonperpetual)
        SELECT ct.apuk_concessiontypeid, ct.apuk_name, ct.apuk_discount, ct.Product_Number,
               ct.statecode, ct.apuk_perpetualnonperpetual
        FROM CE.vwConcessionType AS ct;

        BEGIN TRANSACTION;

        -- Strings compare as bytes so a case-only or trailing-space change in the
        -- source is landed (bronze is byte for byte); EXCEPT treats NULLs as equal.
        UPDATE tgt
        SET apuk_name                  = s.apuk_name,
            apuk_discount              = s.apuk_discount,
            product_number             = s.product_number,
            statecode                  = s.statecode,
            apuk_perpetualnonperpetual = s.apuk_perpetualnonperpetual,
            _is_deleted                = 0,
            _deleted_at                = NULL,
            _updated_at                = SYSDATETIME()
        FROM Layercake.brnz_concession AS tgt
        INNER JOIN #src_concession AS s
            ON s.apuk_concessiontypeid = tgt.apuk_concessiontypeid
        WHERE tgt._is_deleted = 1
           OR EXISTS (SELECT CAST(s.apuk_name AS varbinary(200)), s.apuk_discount,
                             CAST(s.product_number AS varbinary(8000)), s.statecode,
                             s.apuk_perpetualnonperpetual
                      EXCEPT
                      SELECT CAST(tgt.apuk_name AS varbinary(200)), tgt.apuk_discount,
                             CAST(tgt.product_number AS varbinary(8000)), tgt.statecode,
                             tgt.apuk_perpetualnonperpetual);
        SET @upd = @@ROWCOUNT;

        INSERT INTO Layercake.brnz_concession
            (apuk_concessiontypeid, apuk_name, apuk_discount, product_number, statecode, apuk_perpetualnonperpetual)
        SELECT s.apuk_concessiontypeid, s.apuk_name, s.apuk_discount, s.product_number,
               s.statecode, s.apuk_perpetualnonperpetual
        FROM #src_concession AS s
        WHERE NOT EXISTS (SELECT 1
                          FROM Layercake.brnz_concession AS t
                          WHERE t.apuk_concessiontypeid = s.apuk_concessiontypeid);
        SET @ins = @@ROWCOUNT;

        UPDATE tgt
        SET _is_deleted = 1,
            _deleted_at = SYSDATETIME(),
            _updated_at = SYSDATETIME()
        FROM Layercake.brnz_concession AS tgt
        WHERE tgt._is_deleted = 0
          AND NOT EXISTS (SELECT 1
                          FROM #src_concession AS s
                          WHERE s.apuk_concessiontypeid = tgt.apuk_concessiontypeid);
        SET @del = @@ROWCOUNT;

        SELECT @src_count = COUNT_BIG(*) FROM #src_concession;
        SELECT @tgt_count = COUNT_BIG(*) FROM Layercake.brnz_concession WHERE _is_deleted = 0;
        IF @src_count <> @tgt_count
            RAISERROR('Row count mismatch after sync of Layercake.brnz_concession: source %I64d vs active target %I64d.', 16, 1, @src_count, @tgt_count);

        COMMIT TRANSACTION;
        EXEC Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @err = CONCAT(ERROR_MESSAGE(), ' (error ', ERROR_NUMBER(), ', line ', ERROR_LINE(), ')');
        IF @log_id IS NOT NULL
            EXEC Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        THROW;
    END CATCH;
END;
GO
-- Layercake.usp_load_silv_ref_concession_type (src/sql/Layercake/Procedures/Layercake.usp_load_silv_ref_concession_type.sql)
/*====================================================================
    Layercake.usp_load_silv_ref_concession_type
    Silver layer - Layercake.brnz_concession -> Layercake.silv_ref_concession_type
    Insert-and-update from live bronze types (RULE-046): adds new types,
    updates name, item code and flags where they changed, and never changes
    an id. The seeded rows (no business key) and types no longer live in
    bronze are left as they are. Logged.
      item_code          product_number without its 'rcs' prefix (RULE-048)
      is_full_concession 1 where apuk_discount = 100 (RULE-047)
      is_perpetual       1 where apuk_perpetualnonperpetual = 200000000 (RULE-094)
    A type with a NULL, empty or blank name is kept as 'Unnamed concession
    type' (answers 2026-10-27).
====================================================================*/
CREATE OR ALTER PROCEDURE Layercake.usp_load_silv_ref_concession_type
    @run_id uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @run_id IS NULL SET @run_id = NEWID();

    DECLARE @log_id bigint,
            @ins    int,
            @upd    int,
            @now    datetime2(3),
            @err    nvarchar(4000);

    BEGIN TRY
        EXEC Layercake.usp_etl_log_start @run_id, 'silver', 'silv_ref_concession_type', @log_id OUTPUT;

        SET @now = SYSDATETIME();

        -- NULLIF(name, N'') is NULL for NULL, '' and blanks alike, as '=' ignores
        -- trailing spaces. An item code longer than the designed nvarchar(100)
        -- fails the load (truncation error) rather than being cut.
        CREATE TABLE #bronze_type
        (
            concession_type_bk   uniqueidentifier NOT NULL PRIMARY KEY CLUSTERED,
            concession_type_name nvarchar(100) COLLATE DATABASE_DEFAULT NOT NULL,
            item_code            nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            is_full_concession   bit           NOT NULL,
            is_perpetual         bit           NOT NULL
        );

        INSERT INTO #bronze_type
            (concession_type_bk, concession_type_name, item_code, is_full_concession, is_perpetual)
        SELECT b.apuk_concessiontypeid,
               COALESCE(NULLIF(b.apuk_name, N''), N'Unnamed concession type'),
               CASE WHEN b.product_number LIKE N'rcs%' THEN STUFF(b.product_number, 1, 3, N'')
                    ELSE b.product_number
               END,
               CASE WHEN b.apuk_discount = 100 THEN 1 ELSE 0 END,
               CASE WHEN b.apuk_perpetualnonperpetual = 200000000 THEN 1 ELSE 0 END
        FROM Layercake.brnz_concession AS b
        WHERE b._is_deleted = 0;

        BEGIN TRANSACTION;

        -- Strings compare as bytes: the collation is case-insensitive and '='
        -- ignores trailing spaces, and such a change must still reach the list.
        UPDATE t
        SET concession_type_name = s.concession_type_name,
            item_code            = s.item_code,
            is_full_concession   = s.is_full_concession,
            is_perpetual         = s.is_perpetual,
            load_id              = @log_id,
            updated_at           = @now
        FROM Layercake.silv_ref_concession_type AS t
        INNER JOIN #bronze_type AS s
            ON s.concession_type_bk = t.concession_type_bk
        WHERE EXISTS (SELECT CAST(s.concession_type_name AS varbinary(200)), CAST(s.item_code AS varbinary(200)),
                             s.is_full_concession, s.is_perpetual
                      EXCEPT
                      SELECT CAST(t.concession_type_name AS varbinary(200)), CAST(t.item_code AS varbinary(200)),
                             t.is_full_concession, t.is_perpetual);
        SET @upd = @@ROWCOUNT;

        INSERT INTO Layercake.silv_ref_concession_type
            (concession_type_bk, concession_type_name, item_code, is_full_concession, is_perpetual, load_id, created_at, updated_at)
        SELECT s.concession_type_bk, s.concession_type_name, s.item_code, s.is_full_concession, s.is_perpetual,
               @log_id, @now, @now
        FROM #bronze_type AS s
        WHERE NOT EXISTS (SELECT 1
                          FROM Layercake.silv_ref_concession_type AS t
                          WHERE t.concession_type_bk = s.concession_type_bk);
        SET @ins = @@ROWCOUNT;

        COMMIT TRANSACTION;
        EXEC Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @err = CONCAT(ERROR_MESSAGE(), ' (error ', ERROR_NUMBER(), ', line ', ERROR_LINE(), ')');
        IF @log_id IS NOT NULL
            EXEC Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, 0, @err;
        THROW;
    END CATCH;
END;
GO
-- Layercake.usp_load_dim_concession_type (src/sql/Layercake/Procedures/Layercake.usp_load_dim_concession_type.sql)
/*====================================================================
    Layercake.usp_load_dim_concession_type
    Gold layer - Layercake.silv_ref_concession_type -> Layercake.dim_concession_type
    Mirrors the reference list by id, as usp_load_dim_payer_type does:
    inserts missing ids, updates names and flags that changed, leaves
    unchanged rows untouched. Logged. Never deletes: facts may still point
    at an id that left the list.
====================================================================*/
CREATE OR ALTER PROCEDURE Layercake.usp_load_dim_concession_type
    @run_id uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @run_id IS NULL SET @run_id = NEWID();

    DECLARE @log_id bigint,
            @ins    int,
            @upd    int,
            @now    datetime2(3),
            @err    nvarchar(4000);

    BEGIN TRY
        EXEC Layercake.usp_etl_log_start @run_id, 'gold', 'dim_concession_type', @log_id OUTPUT;

        SET @now = SYSDATETIME();

        BEGIN TRANSACTION;

        -- Names compare as bytes: the collation is case-insensitive and '='
        -- ignores trailing spaces, and such a change must still reach the dimension.
        UPDATE d
        SET concession_type_name = s.concession_type_name,
            is_full_concession   = s.is_full_concession,
            is_perpetual         = s.is_perpetual,
            load_id              = @log_id,
            updated_at           = @now
        FROM Layercake.dim_concession_type AS d
        INNER JOIN Layercake.silv_ref_concession_type AS s
            ON s.id = d.id
        WHERE EXISTS (SELECT CAST(s.concession_type_name AS varbinary(200)), s.is_full_concession, s.is_perpetual
                      EXCEPT
                      SELECT CAST(d.concession_type_name AS varbinary(200)), d.is_full_concession, d.is_perpetual);
        SET @upd = @@ROWCOUNT;

        INSERT INTO Layercake.dim_concession_type
            (id, concession_type_name, is_full_concession, is_perpetual, load_id, created_at, updated_at)
        SELECT s.id, s.concession_type_name, s.is_full_concession, s.is_perpetual, @log_id, @now, @now
        FROM Layercake.silv_ref_concession_type AS s
        WHERE NOT EXISTS (SELECT 1 FROM Layercake.dim_concession_type AS d WHERE d.id = s.id);
        SET @ins = @@ROWCOUNT;

        COMMIT TRANSACTION;
        EXEC Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @err = CONCAT(ERROR_MESSAGE(), ' (error ', ERROR_NUMBER(), ', line ', ERROR_LINE(), ')');
        IF @log_id IS NOT NULL
            EXEC Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, 0, @err;
        THROW;
    END CATCH;
END;
